def build_csv_report(report: dict) -> str:
    output = io.StringIO()
    fields = [
        "rank",
        "notice_id",
        "title",
        "agency",
        "posted",
        "deadline",
        "score",
        "recommendation",
        "status",
        "priority",
        "owner",
        "follow_up",
        "naics",
        "psc",
        "set_aside",
        "type",
        "source",
        "source_name",
        "estimated_value",
        "url",
        "why_it_fits",
        "next_action",
    ]
    writer = csv.DictWriter(output, fieldnames=fields)
    writer.writeheader()
    for opp in report.get("matches") or []:
        writer.writerow(
            {
                "rank": opp.get("rank") or "",
                "notice_id": opp.get("noticeId") or "",
                "title": opp.get("title") or "",
                "agency": opp.get("organization") or "",
                "posted": opp.get("postedDisplay") or opp.get("postedDate") or "",
                "deadline": opp.get("dueDisplay") or opp.get("responseDeadline") or "",
                "score": opp.get("score") or "",
                "recommendation": opp.get("recommendation") or "",
                "status": opp.get("workflowStatus") or "",
                "priority": opp.get("workflowPriority") or "",
                "owner": opp.get("workflowOwner") or "",
                "follow_up": opp.get("workflowFollowUpAt") or "",
                "naics": opp.get("naicsCode") or "",
                "psc": opp.get("classificationCode") or "",
                "set_aside": opp.get("setAsideCode") or opp.get("setAside") or "",
                "type": opp.get("type") or "",
                "source": "manual" if opp.get("manualTracked") or opp.get("manualExternal") else "sam.gov",
                "source_name": opp.get("sourceName") or opp.get("source") or "",
                "estimated_value": opp.get("estimatedValue") or "",
                "url": opp.get("url") or sam_url(opp),
                "why_it_fits": opp.get("fitReason") or "",
                "next_action": opp.get("workflowNextAction") or opp.get("nextAction") or "",
            }
        )
    return output.getvalue()


def write_reports(report: dict, settings: Settings) -> dict[str, str]:
    settings.reports_dir.mkdir(parents=True, exist_ok=True)
    slug = dt.datetime.now(ZoneInfo(settings.timezone)).strftime("%Y-%m-%d-%H%M%S")
    html_text = build_html_report(report)
    json_text = json.dumps(report, indent=2, sort_keys=True) + "\n"
    csv_text = build_csv_report(report)
    html_path = settings.reports_dir / f"{slug}.html"
    json_path = settings.reports_dir / f"{slug}.json"
    csv_path = settings.reports_dir / f"{slug}.csv"
    latest_html = settings.reports_dir / "latest.html"
    latest_json = settings.reports_dir / "latest.json"
    latest_csv = settings.reports_dir / "latest.csv"
    html_path.write_text(html_text)
    json_path.write_text(json_text)
    csv_path.write_text(csv_text)
    latest_html.write_text(html_text)
    latest_json.write_text(json_text)
    latest_csv.write_text(csv_text)
    return {
        "htmlPath": str(html_path),
        "jsonPath": str(json_path),
        "csvPath": str(csv_path),
        "latestHtmlPath": str(latest_html),
        "latestJsonPath": str(latest_json),
        "latestCsvPath": str(latest_csv),
        "htmlUrl": f"{settings.report_url_base}/{quote(html_path.name)}",
        "csvUrl": f"{settings.report_url_base}/{quote(csv_path.name)}",
        "latestUrl": settings.latest_report_url,
        "latestCsvUrl": f"{settings.report_url_base}/latest.csv",
    }
